// Simple keyword extraction
function extractSimpleKeywords(text) {
  if (!text) return [];

  const normalized = text.toLowerCase()
    .replace(/[.,\/#!$%\^&\*;:{}=\-_`~()]/g, " ")
    .replace(/\s{2,}/g, " ")
    .trim();

  const words = normalized.split(" ")
    .filter(word => word.length > 2)
    .filter(word => !STOP_WORDS.has(word));

  const freqMap = Object.create(null);
  words.forEach(word => {
    freqMap[word] = (freqMap[word] || 0) + 1;
  });

  return Object.keys(freqMap)
    .sort((a, b) => freqMap[b] - freqMap[a])
    .slice(0, 6);
}

// Extract n-grams (phrases)
function extractNgrams(text, n = 2) {
  if (!text) return [];

  const normalized = text.toLowerCase()
    .replace(/[.,\/#!$%\^&\*;:{}=\-_`~()]/g, " ")
    .replace(/\s{2,}/g, " ")
    .trim();

  const words = normalized.split(" ");
  const ngrams = [];

  for (let i = 0; i <= words.length - n; i++) {
    const ngram = words.slice(i, i + n).join(" ");
    if (!STOP_WORDS.has(words[i]) && !STOP_WORDS.has(words[i + n - 1])) {
      ngrams.push(ngram);
    }
  }

  const freqMap = Object.create(null);
  ngrams.forEach(ngram => {
    freqMap[ngram] = (freqMap[ngram] || 0) + 1; 
  });

  return Object.keys(freqMap)
    .sort((a, b) => freqMap[b] - freqMap[a])
    .slice(0, 3);
}

