const chunks = [];
const chunkSize = 1000;
const chunkOverlap = 100;
const rawText = $json.data || $json.concatenated_data || $json.concatenated_content || $json.text || '';
const text = rawText.replace(/\n/g, '');

for (let i = 0, j = Math.ceil(text.length / chunkSize); i < j; i++) {
  chunks.push(
    text.substr(
      Math.max(0, (i * chunkSize) - chunkOverlap),
      chunkSize
    )
  );
}

//  ————— Sanitization: strip U+FFFD and other control chars —————
const sanitizedChunks = chunks.map(chunk => {
  return chunk
    // Remove replacement characters
    .replace(/[\uFFFD\uFFFC\uFE0F]/g, '')
    // Remove C0 control characters
    .replace(/[\x00-\x1F]/g, '')
    // Remove mathematical alphanumeric symbols (like 𝗖𝗢𝗠𝗕)
    .replace(/[\uD835][\uDC00-\uDFFF]/g, '')
    // Remove any standalone surrogate pairs that might cause issues
    .replace(/[\uD800-\uDBFF][\uDC00-\uDFFF]|[\uD800-\uDFFF]/g, '')
    // Replace any remaining non-standard characters with spaces
    .replace(/[^\x20-\x7E\u00A0-\u00FF\u0100-\u017F\u0180-\u024F\u0300-\u036F\u1E00-\u1EFF]/g, ' ')
    // Clean up by removing multiple spaces
    .replace(/\s+/g, ' ')
    .trim();
});

